SELECT OUT_TB.* FROM ( SELECT IN_TB.* , ROW_NUMBER() OVER (ORDER BY IN_TB.SEQ ) AS RNUM FROM ( SELECT A.SEQ , A.EMP_ID , A.EMP_GRADE , A.EMP_NAME , B.CUST_KOR_NAME , A.DEPT_NAME , A.DEPT_GRADE , A.TEL_NO , A.EMAIL , A.USE_TYPE , A.JOIN_DATE , (SELECT CODE_NAME FROM CRM_CODE_DETAIL Z WHERE CODE_GROUP='COMMON' AND P_CODE ='CD01' AND CODE = A.EMP_GRADE) EMP_GRADE_NAME , (SELECT CODE_NAME FROM CRM_CODE_DETAIL Z WHERE CODE_GROUP='COMMON' AND P_CODE ='CD02' AND CODE = A.USE_TYPE) USE_TYPE_NAME FROM CRM_CUST_ERP A INNER JOIN CRM_CUST_MGT B ON A.CUST_CODE = B.CRM_CODE ) IN_TB WHERE 1=1
) OUT_TB
WHERE RNUM BETWEEN #{startRow} AND #{endRow}
ORDER BY RNUM DESC

