SELECT IN_TB.* FROM( SELECT SEQ , CUST_KOR_NAME , CUST_ADDRESS , CUST_NO , CRM_CODE, CEO , ROW_NUMBER() OVER (ORDER BY A.SEQ ) AS RNUM FROM CRM_CUST_MGT A
WHERE UPPER(A.CUST_KOR_NAME) LIKE '%'|| UPPER(#{search_text}) ||'%'
) IN_TB WHERE RNUM BETWEEN #{startRow, jdbcType=INTEGER} AND #{endRow, jdbcType=INTEGER} ORDER BY RNUM DESC

SELECT OUT_TB.* FROM ( SELECT IN_TB.* , ROW_NUMBER() OVER (ORDER BY IN_TB.EMP_NO ) AS RNUM FROM ( SELECT A.EMP_NO , A.EMP_GRADE , A.EMP_NM , A.DEPT_CD , A.MOBILE_NO , A.E_MAIL , A.RETIRE_DATE , A.REG_DATE , (SELECT CODE_NAME FROM CRM_CODE_DETAIL Z WHERE CODE_GROUP='COMMON' AND P_CODE ='CD04' AND CODE = A.EMP_GRADE) EMP_GRADE_NAME , (SELECT DEPT_NM FROM KYERP.TB_HR_DEPARTMENT AA WHERE AA.DEPT_CD = A.DEPT_CD AND END_YMD = '99991231' ) DEPT_NM , DECODE(RETIRE_DATE,NULL,'Y','N') USE_YN FROM CRM_EMP_MGT A
) IN_TB WHERE 1=1
) OUT_TB
WHERE RNUM BETWEEN #{startRow} AND #{endRow}
ORDER BY RNUM DESC

