SELECT OUT_TB.* FROM ( SELECT IN_TB.* , ROW_NUMBER() OVER (ORDER BY IN_TB.SEQ ) AS RNUM FROM ( SELECT SEQ , CUST_CODE , EMP_ID , EMP_NAME , TEL_NO FROM CRM_CUST_ERP ) IN_TB WHERE 1 =1
AND CUST_CODE = #{cust_code}
AND UPPER(EMP_NAME) LIKE '%'|| UPPER(#{search_text}) ||'%'
) OUT_TB WHERE RNUM BETWEEN #{startRow, jdbcType=INTEGER} AND #{endRow, jdbcType=INTEGER} ORDER BY RNUM DESC

